const $=id=>document.getElementById(id);
let settings={method:'2',school:'0'}, saved=null, data=null, bearing=null, heading=null, sensorTimer, loading=false, tomorrow=null;
try{settings={...settings,...JSON.parse(localStorage.getItem('sakinah-settings')||'{}')};saved=JSON.parse(localStorage.getItem('sakinah-place')||'null')}catch{}
$('method').value=settings.method;$('school').value=settings.school;
const prayers=[['Fajr','الفجر','☼'],['Sunrise','الشروق','☀'],['Dhuhr','الظهر','☀'],['Asr','العصر','◔'],['Maghrib','المغرب','☾'],['Isha','العشاء','✧']];
function localDate(zone,offset=0){const parts=new Intl.DateTimeFormat('en-CA',{timeZone:zone||Intl.DateTimeFormat().resolvedOptions().timeZone,year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date());const get=k=>parts.find(p=>p.type===k).value;const d=new Date(Date.UTC(+get('year'),+get('month')-1,+get('day')+offset));return `${String(d.getUTCDate()).padStart(2,'0')}-${String(d.getUTCMonth()+1).padStart(2,'0')}-${d.getUTCFullYear()}`}
async function api(place,date){let endpoint=place.coords?'timings':'timingsByAddress';let q=new URLSearchParams({method:settings.method,school:settings.school,iso8601:'true'});if(place.coords){q.set('latitude',place.coords[0]);q.set('longitude',place.coords[1])}else q.set('address',place.query);const res=await fetch(`https://api.aladhan.com/v1/${endpoint}/${date}?${q}`,{signal:AbortSignal.timeout(18000)});if(!res.ok)throw Error('Prayer service is unavailable. Please try again.');const json=await res.json();if(json.code!==200||!json.data?.timings)throw Error('Location not found. Try a city with its country, or a US ZIP code.');return json.data}
async function load(place){if(loading)return;loading=true;$('status').textContent='Finding your location and prayer times…';$('search').querySelector('button').disabled=true;tomorrow=null;try{let result=await api(place,localDate());const target=localDate(result.meta.timezone);if(target!==localDate())result=await api(place,target);data=result;saved=place;localStorage.setItem('sakinah-place',JSON.stringify(place));localStorage.setItem('sakinah-cache',JSON.stringify({data,place,settings}));render();$('status').textContent='✓ Updated for your location · Times shown in '+data.meta.timezone;try{tomorrow=await api(place,localDate(data.meta.timezone,1));tick()}catch{}}catch(e){$('status').textContent=e.message||'Could not load times. Check your connection and try again.'}finally{loading=false;$('search').querySelector('button').disabled=false}}
function qibla(lat,lon){const r=Math.PI/180,p1=lat*r,p2=21.422487*r,d=(39.826206-lon)*r;return (Math.atan2(Math.sin(d),Math.cos(p1)*Math.tan(p2)-Math.sin(p1)*Math.cos(d))/r+360)%360}
function timeLabel(value){const d=new Date(value);if(!Number.isFinite(+d))return '—';return new Intl.DateTimeFormat('en-US',{hour:'numeric',minute:'2-digit',hour12:true,timeZone:data.meta.timezone}).format(d)}
function render(){const zone=data.meta.timezone;$('place').textContent=saved.label;$('location').value=saved.query||'';$('date').textContent=new Intl.DateTimeFormat('en-US',{weekday:'short',month:'short',day:'numeric',year:'numeric',timeZone:zone}).format(new Date(data.timings.Dhuhr));$('hijri').textContent=`${data.date.hijri.day} ${data.date.hijri.month.en} ${data.date.hijri.year} AH`;$('zone').textContent=zone.replaceAll('_',' ');$('times').replaceChildren();for(const [name,arabic,icon] of prayers){const row=document.createElement('div');row.className='time-row';row.dataset.prayer=name;const label=timeLabel(data.timings[name]);row.innerHTML=`<span class="time-icon">${icon}</span><span class="time-name">${name}</span><span class="time-arabic" lang="ar">${arabic}</span><span class="time-value">${label.replace(/ (AM|PM)/,' <small>$1</small>')}</span>`;$('times').append(row)}bearing=qibla(data.meta.latitude,data.meta.longitude);$('bearing').textContent=bearing.toFixed(1)+'°';updateCompass();updateClock();tick()}
function tick(){if(!data)return;const now=Date.now(), list=prayers.filter(p=>p[0]!=='Sunrise');let next=list.find(p=>+new Date(data.timings[p[0]])>now),target=next?+new Date(data.timings[next[0]]):tomorrow?+new Date(tomorrow.timings.Fajr):null;if(!next)next=['Fajr'];$('next-name').textContent=next[0];$('next-label').textContent='NEXT PRAYER'+(!list.some(p=>+new Date(data.timings[p[0]])>now)?' · TOMORROW':'');if(target){const mins=Math.max(0,Math.ceil((target-now)/60000));$('countdown').textContent=`In ${Math.floor(mins/60)}h ${String(mins%60).padStart(2,'0')}m · ${timeLabel(new Date(target).toISOString())}`}else $('countdown').textContent='Refresh to see the next prayer time';document.querySelectorAll('.time-row').forEach(r=>r.classList.toggle('active',r.dataset.prayer===next[0]));if(localDate(data.meta.timezone)!==data.date.gregorian.date&&!loading&&navigator.onLine)load(saved)}
function updateCompass(){if(bearing===null)return;$('pointer').style.transform=`rotate(${bearing-(heading??0)}deg)`;$('dial').style.transform=`rotate(${-(heading??0)}deg)`;$('compass-help').textContent=heading===null?`Qibla is ${bearing.toFixed(1)}° clockwise from north. Allow the live compass to follow your phone.`:Math.abs(((bearing-heading+540)%360)-180)<6?'You’re facing the Qibla.':`Turn your phone until the Kaaba points straight ahead.`}
$('search').onsubmit=e=>{e.preventDefault();let query=$('location').value.trim();if(!query)return;load({query:/^\d{5}$/.test(query)?query+', USA':query,label:query})};
function detectLocation(){return new Promise(resolve=>{if(!navigator.geolocation){$('status').textContent='Location is unavailable. Enter your city instead.';resolve(false);return}$('status').textContent='Detecting your location… Allow location access when asked.';navigator.geolocation.getCurrentPosition(async p=>{await load({coords:[p.coords.latitude,p.coords.longitude],label:'Current location'});resolve(true)},()=>{$('status').textContent='Automatic location unavailable. Use your saved location or enter a city or ZIP code.';resolve(false)},{enableHighAccuracy:true,timeout:15000,maximumAge:300000})})}
$('locate').onclick=detectLocation;
function orientation(e){let value=typeof e.webkitCompassHeading==='number'&&e.webkitCompassHeading>=0?e.webkitCompassHeading:e.absolute&&typeof e.alpha==='number'?(360-e.alpha)%360:null;if(value===null)return;clearTimeout(sensorTimer);heading=value;updateCompass();$('enable-compass').textContent='✓ Live compass enabled'}
function listenForCompass(){window.addEventListener('deviceorientation',orientation);window.addEventListener('deviceorientationabsolute',orientation);if(heading!==null)return;$('compass-help').textContent='Waiting for compass sensor… Keep your phone flat.';clearTimeout(sensorTimer);sensorTimer=setTimeout(()=>{if(heading===null)$('compass-help').textContent='No compass reading available. Use the displayed bearing with a physical compass.'},6000)}
function autoCompass(){if(!window.DeviceOrientationEvent){$('compass-help').textContent='No compass sensor detected. Use the displayed bearing with a physical compass.';return}if(typeof DeviceOrientationEvent.requestPermission==='function'){$('enable-compass').textContent='◎ Allow live compass';$('compass-help').textContent='Live compass is ready. Tap Allow live compass to grant iPhone sensor access.';window.addEventListener('deviceorientation',orientation);window.addEventListener('deviceorientationabsolute',orientation)}else listenForCompass()}
$('enable-compass').onclick=async()=>{try{if(!window.DeviceOrientationEvent)throw Error('No compass sensor detected. Use the bearing with a physical compass.');if(typeof DeviceOrientationEvent.requestPermission==='function'){if(await DeviceOrientationEvent.requestPermission(true)!=='granted')throw Error('Compass permission denied. You can still use the bearing from north.')}listenForCompass()}catch(e){$('compass-help').textContent=e.message}};
function updateClock(){const zone=data?.meta.timezone;$('current-time').textContent=new Intl.DateTimeFormat('en-US',{hour:'numeric',minute:'2-digit',second:'2-digit',hour12:true,...(zone?{timeZone:zone}:{})}).format(new Date());$('current-time').dateTime=new Date().toISOString();$('clock-zone').textContent=zone?zone.replaceAll('_',' '):'Your device’s local time'}
function applyTheme(theme){document.documentElement.dataset.theme=theme;const dark=theme==='dark';$('theme-toggle').innerHTML=dark?'☀ <span>Light mode</span>':'☾ <span>Dark mode</span>';$('theme-toggle').setAttribute('aria-label',dark?'Switch to light mode':'Switch to dark mode');$('theme-toggle').setAttribute('aria-pressed',String(dark));document.querySelector('meta[name="theme-color"]').content=dark?'#101d1a':'#f7f6ef'}
applyTheme(document.documentElement.dataset.theme);$('theme-toggle').onclick=()=>{const theme=document.documentElement.dataset.theme==='dark'?'light':'dark';applyTheme(theme);try{localStorage.setItem('sakinah-theme',theme)}catch{}};updateClock();setInterval(updateClock,1000);
$('settings-open').onclick=()=>$('settings').showModal();$('save-settings').onclick=()=>{settings={method:$('method').value,school:$('school').value};localStorage.setItem('sakinah-settings',JSON.stringify(settings));if(saved)load(saved)};
function info(html){$('info-body').innerHTML=html;$('info').showModal()}$('info-close').onclick=()=>$('info').close();$('install').onclick=()=>info('<p class="eyebrow">TAKE ADHAN WITH YOU</p><h2>A place on your Home Screen</h2><p>On your iPhone, open this app in <strong>Safari</strong>, tap <strong>Share</strong> (the square with an up arrow), then <strong>Add to Home Screen</strong>. If shown, turn on <strong>Open as Web App</strong>, then tap <strong>Add</strong>.</p><p>On Android, use your browser menu and choose <strong>Install app</strong> or <strong>Add to Home screen</strong>.</p><p class="fine">The last loaded schedule stays available offline. Connect to the internet to search or update times.</p>');$('about').onclick=()=>info('<p class="eyebrow">A LITTLE CONTEXT</p><h2>Prayer times & direction</h2><p>Prayer times come from <a href="https://aladhan.com/prayer-times-api" target="_blank" rel="noopener">AlAdhan</a>, with your selected calculation method and Asr school. Check your local mosque for adjustments. Hijri dates may differ with local moon sighting.</p><p>The Qibla bearing uses the great-circle direction to the Kaaba in Makkah. Phone sensors can be affected by nearby metal and magnetic interference.</p><p>Your saved location and preferences stay in this browser. Location searches and coordinates are sent to AlAdhan to retrieve times.</p>');
setInterval(tick,30000);document.addEventListener('visibilitychange',()=>{if(!document.hidden)tick()});window.addEventListener('online',()=>{if(saved)load(saved)});
try{const cache=JSON.parse(localStorage.getItem('sakinah-cache')||'null');if(cache){data=cache.data;saved=cache.place;render();$('status').textContent='Saved schedule · '+data.date.readable+(navigator.onLine?' · Updating…':' · Offline')}}catch{}
$('date').textContent=new Intl.DateTimeFormat('en-US',{weekday:'short',month:'short',day:'numeric',year:'numeric'}).format(new Date());
autoCompass();
(async()=>{const found=await detectLocation();if(!found&&saved)await load(saved)})();
if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});
